import{_ as a,o as t,c as r,a3 as o}from"./chunks/framework.DAK02U1-.js";const u=JSON.parse('{"title":"什么是 Catter？","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"什么是 Catter？ | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/catter/guide/what-is-catter"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/catter/guide/what-is-catter"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/catter/guide/what-is-catter"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/catter/guide/what-is-catter"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/catter/guide/what-is-catter"}]]},"headers":[],"relativePath":"zh/catter/guide/what-is-catter.md","filePath":"zh/catter/guide/what-is-catter.md","lastUpdated":1793091486000}'),c={name:"zh/catter/guide/what-is-catter.md"};function i(l,e,n,h,d,s){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="什么是-catter" tabindex="-1">什么是 Catter？ <a class="header-anchor" href="#什么是-catter" aria-label="Permalink to &quot;什么是 Catter？&quot;">​</a></h1><p>Catter 是一个构建过程拦截工具。它通过钩子拦截构建过程中的子进程创建，捕获编译和链接命令，并让你用它的内置功能或 handler 处理这些命令。handler 是你自己编写的程序，可以用任何语言实现。</p><h2 id="动机" tabindex="-1">动机 <a class="header-anchor" href="#动机" aria-label="Permalink to &quot;动机&quot;">​</a></h2><p>Catter 是为 <a href="https://github.com/clice-io/clice" target="_blank" rel="noreferrer">clice</a> 这个新的 C++ 语言服务器而创建的。语言服务器依赖<a href="https://clang.llvm.org/docs/JSONCompilationDatabase.html" target="_blank" rel="noreferrer">编译数据库 (CDB)</a> 来了解每个源文件的编译方式，但获取 CDB 往往非常困难：</p><ul><li><strong>构建系统支持有限</strong> -- CMake 仅在使用 Makefile 或 Ninja 后端时才能生成 CDB。许多其他流行的 C++ 构建系统完全没有原生 CDB 支持。</li><li><strong>构建目录不可访问</strong> -- 当 C++ 代码作为 Python 包（或类似形式）的一部分进行构建时，构建目录由外部管理，生成的 CDB 文件无法获取。</li><li><strong>代码生成器需要完整构建</strong> -- 像 LLVM 这样的项目使用 <code>tablegen</code> 等工具在构建时生成头文件。这些文件通过 <code>-I</code> 标志在编译命令中被引用，因此在完整构建之前，语言服务器无法正确解析 include 路径——即使你只是想阅读代码。</li></ul><p>目前没有跨平台工具能够完整解决上述所有问题，这就是我们创建 catter 的原因。</p><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>Catter 的方式类似于 <a href="https://github.com/rizsotto/Bear" target="_blank" rel="noreferrer">Bear</a> 和 <a href="https://github.com/rizsotto/scan-build" target="_blank" rel="noreferrer">scan-build</a>。它使用平台特定的钩子（Linux 上的 <code>LD_PRELOAD</code>、macOS 上的 <code>DYLD_INSERT_LIBRARIES</code>、Windows 上的 DLL 注入）拦截子进程创建。每个被拦截的命令会发送到一个决策守护进程，由它询问会话的各个 handler 如何处理这条命令。</p><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to &quot;核心功能&quot;">​</a></h2><h3 id="编译数据库生成" tabindex="-1">编译数据库生成 <a class="header-anchor" href="#编译数据库生成" aria-label="Permalink to &quot;编译数据库生成&quot;">​</a></h3><p>最主要的用例。Catter 可以跨任意构建系统捕获编译器调用，生成标准的 <code>compile_commands.json</code>，无需构建系统插件或特殊配置。</p><h3 id="链接器分析" tabindex="-1">链接器分析 <a class="header-anchor" href="#链接器分析" aria-label="Permalink to &quot;链接器分析&quot;">​</a></h3><p>通过捕获链接器命令，catter 可以重建构建目标之间的依赖图。这对 C++20 模块支持至关重要：C++ 标准规定一个程序中同名模块最多只能有一个，而&quot;程序&quot;由目标（库、可执行文件）定义。这些目标信息在 CDB 标准中是缺失的，但 catter 可以从链接器命令中推断出来。</p><h3 id="伪编译-计划中" tabindex="-1">伪编译（计划中） <a class="header-anchor" href="#伪编译-计划中" aria-label="Permalink to &quot;伪编译（计划中）&quot;">​</a></h3><p>不将编译任务转发给真正的编译器，catter 将能够生成占位目标文件。这使得构建系统可以正常运行而无需实际编译，从而在极短的时间内生成完整的 CDB。代码生成器（如 <code>tablegen</code>）仍然会正常构建——catter 会分析依赖关系以确定必须真正编译的最小工具集。</p><h3 id="构建分析-计划中" tabindex="-1">构建分析（计划中） <a class="header-anchor" href="#构建分析-计划中" aria-label="Permalink to &quot;构建分析（计划中）&quot;">​</a></h3><p>捕获构建过程中的进程时间、持续时间和父子关系，可以在浏览器中可视化渲染，帮助分析构建并行度和识别性能瓶颈。</p><h3 id="自定义-handler" tabindex="-1">自定义 handler <a class="header-anchor" href="#自定义-handler" aria-label="Permalink to &quot;自定义 handler&quot;">​</a></h3><p>handler 是你自己编写的程序，catter 通过一个简单的协议与它通信。它可以观察每条命令，也可以对每条命令做决定：原样运行、换成另一条命令运行、丢弃，或中止构建——无需修改原始构建文件。Python 和 TypeScript 的 SDK 替你处理协议。</p><h2 id="架构概览" tabindex="-1">架构概览 <a class="header-anchor" href="#架构概览" aria-label="Permalink to &quot;架构概览&quot;">​</a></h2><p>Catter 围绕 <strong>捕获后端</strong>（capture backend）展开：捕获后端是 catter 获取构建命令的方式。默认的 <code>hook</code> 后端通过平台钩子（Linux 的 <code>LD_PRELOAD</code>、macOS 的 <code>DYLD_INSERT_LIBRARIES</code>、Windows 的 DLL 注入）拦截子进程创建；捕获到的每条命令都会交给守护进程，再由守护进程转给会话的各个 handler。</p><p>handler 会在这些时刻收到通知：会话开始时（同时得知命令以何种方式捕获）、每条命令运行前和运行后，以及构建结束时。做决定的 handler 决定每条命令原样运行、修改后运行、丢弃，还是中止构建；不做决定的 handler 只观察。</p><p>关于架构概念、捕获后端和 IPC 流程的详细介绍，请参阅<a href="./../design/architecture">设计文档</a>与<a href="./../design/capture-backends">捕获后端</a>。</p>',23)])])}const g=a(c,[["render",i]]);export{u as __pageData,g as default};
